DROP TABLE IF EXISTS `admin_recommend`;
CREATE TABLE `admin_recommend`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '推荐id',
  `admin_id` bigint NOT NULL COMMENT '推荐人id',
  `book_id` bigint NOT NULL COMMENT '推荐书籍id',
  `category_id` smallint NULL DEFAULT NULL COMMENT '分类id',
  `recommend_status` tinyint NOT NULL DEFAULT 0 COMMENT '推荐状态（0-启用，1-禁用）',
  `recommend_type` tinyint NOT NULL COMMENT '推荐类型（1-首页推荐，2-分类页轮播）',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序字段（值越小越靠前）',
  `start_time` datetime NOT NULL COMMENT '起始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_recommend_query`(`recommend_type`, `category_id`, `recommend_status`, `start_time`, `end_time`, `sort`) USING BTREE,
  INDEX `idx_book_id`(`book_id`) USING BTREE,
  INDEX `idx_admin_id`(`admin_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '管理员推荐表' ROW_FORMAT = Dynamic;

